INSERT INTO "MapSubmissionMetadata" ("mapId","submissionType","challengePlacement","challengeLevel") SELECT c."id",CASE WHEN c."isAutoImported" THEN 'ranked' ELSE 'challenge' END,CASE WHEN c."isAutoImported" THEN NULL ELSE 'main' END,NULL FROM "ChallengeMap" c LEFT JOIN "MapSubmissionMetadata" m ON m."mapId"=c."id" WHERE m."mapId" IS NULL;
INSERT INTO "MapSubmissionMetadata" ("mapId","submissionType","challengePlacement","challengeLevel") SELECT c."id",'challenge',c."category",c."level" FROM "CategoryMap" c LEFT JOIN "MapSubmissionMetadata" m ON m."mapId"=c."id" WHERE m."mapId" IS NULL;